SELECT * FROM LATERAL ( (SELECT "QUERIES_CELEBRITY"."ID" AS "COL1", "QUERIES_CELEBRITY"."NAME" AS "COL2", "QUERIES_CELEBRITY"."GREATEST_FAN_ID" AS "COL3" FROM "QUERIES_CELEBRITY" WHERE "QUERIES_CELEBRITY"."NAME" = %s) UNION (SELECT "QUERIES_CELEBRITY"."ID" AS "COL1", "QUERIES_CELEBRITY"."NAME" AS "COL2", "QUERIES_CELEBRITY"."GREATEST_FAN_ID" AS "COL3" FROM "QUERIES_CELEBRITY") ) ORDER BY "COL2" ASC OFFSET 1 ROWS FETCH FIRST 1 ROWS ONLY;
