SELECT * FROM LATERAL ( (SELECT "QUERIES_CELEBRITY"."ID" AS "PK", "QUERIES_CELEBRITY"."NAME" AS "__ORDERBYCOL2" FROM "QUERIES_CELEBRITY") UNION (SELECT "QUERIES_RESERVEDNAME"."ID" AS "PK", "QUERIES_RESERVEDNAME"."NAME" AS "__ORDERBYCOL2" FROM "QUERIES_RESERVEDNAME") ) ORDER BY "__ORDERBYCOL2" ASC;
