SELECT * FROM LATERAL ( (SELECT "QUERIES_NUMBER"."ID" AS "COL1", "QUERIES_NUMBER"."NUM" AS "COL2", "QUERIES_NUMBER"."OTHER_NUM" AS "COL3", "QUERIES_NUMBER"."ANOTHER_NUM" AS "COL4" FROM "QUERIES_NUMBER") UNION (SELECT "QUERIES_NUMBER"."ID" AS "COL1", "QUERIES_NUMBER"."NUM" AS "COL2", "QUERIES_NUMBER"."OTHER_NUM" AS "COL3", "QUERIES_NUMBER"."ANOTHER_NUM" AS "COL4" FROM "QUERIES_NUMBER") ) ORDER BY "COL3" ASC;
