SELECT * FROM LATERAL ( (SELECT "QUERIES_NUMBER"."NUM" AS "ALIAS" FROM "QUERIES_NUMBER" WHERE "QUERIES_NUMBER"."NUM" <= %s) UNION (SELECT "QUERIES_NUMBER"."NUM" AS "ALIAS" FROM "QUERIES_NUMBER" WHERE ("QUERIES_NUMBER"."NUM" >= %s AND "QUERIES_NUMBER"."NUM" <= %s)) ) ORDER BY 1 DESC;
