SELECT "QUERIES_TICKET23605APARENT"."ID", "QUERIES_TICKET23605A"."TICKET23605APARENT_PTR_ID" FROM "QUERIES_TICKET23605A" INNER JOIN "QUERIES_TICKET23605APARENT" ON ("QUERIES_TICKET23605A"."TICKET23605APARENT_PTR_ID" = "QUERIES_TICKET23605APARENT"."ID") WHERE NOT ("QUERIES_TICKET23605A"."TICKET23605APARENT_PTR_ID" IN (SELECT W0."TICKET23605APARENT_PTR_ID" FROM "QUERIES_TICKET23605A" W0 INNER JOIN "QUERIES_TICKET23605B" W1 ON (W0."TICKET23605APARENT_PTR_ID" = W1."MODELA_FK_ID") INNER JOIN "QUERIES_TICKET23605C" W2 ON (W1."MODELC_FK_ID" = W2."ID") INNER JOIN "QUERIES_TICKET23605B" W3 ON (W0."TICKET23605APARENT_PTR_ID" = W3."MODELA_FK_ID") WHERE (W1."FIELD_B0" >= (CAST(%s AS INTEGER) / W2."FIELD_C0") AND W1."FIELD_B1" = TRUE AND NOT (EXISTS(SELECT (1) AS "A" FROM "QUERIES_TICKET23605B" V1 WHERE (V1."ID" IN (SELECT U0."ID" FROM "QUERIES_TICKET23605B" U0 INNER JOIN "QUERIES_TICKET23605C" U1 ON (U0."MODELC_FK_ID" = U1."ID") WHERE NOT (U0."FIELD_B1" = TRUE AND U0."FIELD_B0" >= (CAST(%s AS INTEGER) / U1."FIELD_C0") AND U0."FIELD_B0" IS NOT NULL)) AND V1."ID" = (W1."ID")) FETCH FIRST 1 ROWS ONLY)) AND W3."FIELD_B1" = TRUE)));
